  "heroic_pose_database": {
    "_hint": "[CHOREOGRAPHY GENERATION] Refer to 'key visual' level pose data from movies, games, and anime to eliminate amateurish results.",
    "retrieval_logic": {
      "source": "cinematic_combat_pose_db",
      "query_parameters": [
        "weapon_type",
        "character_physique",
        "desired_coolness_factor"
      ],
      "pose_correction": {
        "line_of_action": "strong_s_curve_or_c_curve_body_line",
        "silhouette_check": "ensure_weapon_is_clearly_visible_against_background"
